// =====================================================================
//  WIZZIE FARM — SPELL CARD ART  (WF.cardArt)            v1.2 WS8
//  Every spell card has a painted illustration that shows what it does
//  (the summoned creature for attacks, a raised blade for blades, a rune
//  snare for traps, a heal fairy / glowing heart for heals...).
//  The pictures are pre-baked by tools/bake-card-art.js into
//  game/img/cards/<cardId>.webp; the manifest game/data/cardart.js
//  (generated by the same tool) lists which cards have one.
//
//  API
//    WF.cardArt.has(cardId)    true when the card has a baked picture
//    WF.cardArt.url(cardId)    URL of the picture (relative to the page), or null
//    WF.cardArt.imgHTML(cardId, cls)  '<img ...>' that removes itself (and marks its
//                              parent .noart) if the file is missing, or ''
//  Cards without art keep the classic type glyph (UI.cardEl does the fallback).
//  Images are used through <img>/CSS only (works from file://). Do NOT draw
//  them into WebGL textures: file:// images taint canvases.
// =====================================================================
window.WF = window.WF || { data: {} };

WF.cardArt = (function () {
  'use strict';
  // folder of game/ relative to the page that loaded us ("game/" for Play Wizzie Farm.html,
  // "../game/" for the test pages), worked out from this script's own URL
  var base = 'game/';
  try {
    var cs = document.currentScript, src = cs && cs.getAttribute('src');
    if (src && /js\/cardart\.js(\?.*)?$/.test(src)) base = src.replace(/js\/cardart\.js(\?.*)?$/, '');
  } catch (e) { /* not in a browser (node tests) */ }

  function man() { return (WF.data && WF.data.cardArt) || { cards: {} }; }
  var A = { base: base };
  A.has = function (id) {
    var c = man().cards;
    return !!(id && c && Object.prototype.hasOwnProperty.call(c, id));
  };
  A.url = function (id) {
    if (!A.has(id)) return null;
    var m = man(), v = m.cards[id];
    return A.base + (m.dir || 'img/cards/') + id + '.' + (typeof v === 'string' && v ? v : (m.ext || 'webp'));
  };
  A.count = function () { return Object.keys(man().cards || {}).length; };
  A.imgHTML = function (id, cls) {
    var u = A.url(id);
    if (!u) return '';
    return '<img class="' + (cls || 'c-img') + '" src="' + u + '" alt="" draggable="false" decoding="async" ' +
      'onerror="if(this.parentNode)this.parentNode.classList.add(\'noart\');this.remove()">';
  };
  return A;
})();
